<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment receipt {{ $payment->gateway_id }}</title><style>body{font:16px/1.6 system-ui;max-width:700px;margin:40px auto;padding:20px;color:#182b24}dt{font-weight:600}dd{margin:0 0 16px;overflow-wrap:anywhere}@media print{button{display:none}}</style></head><body><h1>MetoHub payment receipt</h1><p>Store software subscription · {{ $tenant->name }}</p><dl><dt>Payment reference</dt><dd>{{ $payment->gateway_id }}</dd><dt>Subscription reference</dt><dd>{{ $payment->subscription->gateway_id }}</dd><dt>Amount captured</dt><dd>{{ $payment->currency }} {{ number_format($payment->amount / 100, 2) }}</dd><dt>Amount refunded</dt><dd>{{ $payment->currency }} {{ number_format($payment->amount_refunded / 100, 2) }}</dd><dt>Provider payment date</dt><dd>{{ $payment->paid_at?->format('d M Y, H:i') ?: 'Not recorded' }}</dd><dt>Provider invoice reference</dt><dd>{{ $payment->invoice_id ?: 'Not recorded' }}</dd></dl><p>This acknowledges the recorded payment. Obtain a tax invoice from MetoHub support where applicable.</p><button onclick="window.print()">Print receipt</button></body></html>
